import type { Metadata } from "next";
import Link from "next/link";
import { PublicHeader } from "@/components/public-header";
import { PublicFooter } from "@/components/public-footer";
import { ArticleCard } from "@/components/blog/article-card";
import { getCurrentUser } from "@/lib/auth/session";
import { listPublishedPosts, coverUrl } from "@/lib/blog/service";
import { CATEGORY_LABELS, POST_CATEGORIES, type PostCategory } from "@/lib/blog/core";
import { getPreferences } from "@/lib/i18n/get-translations";

export const metadata: Metadata = { title: "Kiến thức TOEIC: lộ trình, chiến thuật và luyện thi", description: "Hướng dẫn TOEIC thực tế về Listening, Reading, ngữ pháp, từ vựng, lộ trình học và kinh nghiệm ngày thi.", alternates: { canonical: "/blog" }, openGraph: { title: "Kiến thức TOEIC | TOEICGym", description: "Học TOEIC có định hướng: hiểu điểm yếu, chọn đúng nội dung và áp dụng ngay vào bài luyện.", type: "website", images: ["/blog/cover/toeic_strategy"] } };

const categoryNotes: Record<PostCategory, { vi: string; en: string }> = {
  TOEIC_STRATEGY: { vi: "Tăng điểm có chiến lược", en: "Score-growth strategy" }, LISTENING: { vi: "Nghe ý, bắt paraphrase", en: "Listen for meaning" }, READING: { vi: "Đọc nhanh, giữ độ chính xác", en: "Read faster accurately" }, GRAMMAR: { vi: "Ngữ pháp tạo điểm", en: "High-value grammar" }, VOCABULARY: { vi: "Từ vựng theo ngữ cảnh", en: "Vocabulary in context" }, STUDY_PLAN: { vi: "Lịch học duy trì được", en: "Sustainable study plans" }, EXAM_TIPS: { vi: "Sẵn sàng cho ngày thi", en: "Test-day readiness" },
};

type Search = { category?: string; q?: string };
export default async function BlogPage({ searchParams }: { searchParams: Promise<Search> }) {
  const user = await getCurrentUser();
  const [{ category, q }, prefs, posts] = await Promise.all([searchParams, getPreferences(user?.id), listPublishedPosts()]);
  const locale = prefs.interfaceLanguage;
  const activeCategory = POST_CATEGORIES.includes(category as PostCategory) ? category as PostCategory : null;
  const query = q?.trim().toLocaleLowerCase(locale === "vi" ? "vi" : "en") ?? "";
  const filtered = posts.filter(post => (!activeCategory || post.category === activeCategory) && (!query || `${post.title} ${post.excerpt} ${post.content}`.toLocaleLowerCase(locale === "vi" ? "vi" : "en").includes(query)));
  const cards = await Promise.all(filtered.map(async post => ({ post, image: await coverUrl(post.coverMediaId) || `/blog/cover/${post.category.toLowerCase()}` })));
  const featured = cards[0], remaining = cards.slice(1);
  return <main className="min-h-screen bg-[#f4f1e8] text-slate-950">
    <PublicHeader locale={locale} signedIn={Boolean(user)} />
    <header className="relative overflow-hidden border-b border-slate-900/10 bg-[#f4f1e8]"><div aria-hidden="true" className="absolute inset-0 bg-[radial-gradient(circle_at_85%_10%,rgba(13,148,136,.16),transparent_30%),linear-gradient(90deg,rgba(15,23,42,.04)_1px,transparent_1px)] bg-[size:auto,34px_34px]"/><div className="relative mx-auto grid max-w-7xl gap-10 px-5 py-14 sm:px-6 sm:py-20 lg:grid-cols-[1.15fr_.85fr] lg:items-end"><div><p className="text-sm font-black uppercase tracking-[.2em] text-teal-800">TOEIC GYM · FIELD NOTES</p><h1 className="mt-5 max-w-4xl font-serif text-5xl font-black leading-[.98] tracking-tight sm:text-7xl">{locale === "vi" ? <>Học TOEIC có <span className="text-teal-800">định hướng.</span></> : <>TOEIC learning, <span className="text-teal-800">with direction.</span></>}</h1><p className="mt-6 max-w-2xl text-lg leading-8 text-slate-700">{locale === "vi" ? "Chiến thuật, kiến thức và lộ trình được viết để trả lời một câu hỏi: buổi học tiếp theo của bạn nên tập trung vào đâu?" : "Strategies, knowledge and plans written to answer one question: what should your next study session focus on?"}</p></div><aside className="border-l-4 border-teal-700 pl-6"><p className="text-xs font-black uppercase tracking-[.18em] text-slate-500">{locale === "vi" ? "Bắt đầu từ đây" : "Start here"}</p><p className="mt-3 text-xl font-black">{locale === "vi" ? "Chưa biết mình yếu phần nào?" : "Not sure where you are weak?"}</p><p className="mt-2 leading-7 text-slate-600">{locale === "vi" ? "Làm bài đánh giá ngắn, sau đó quay lại chọn bài đọc phù hợp với kết quả." : "Take a short diagnostic, then return for guides that match your result."}</p><Link className="mt-5 inline-flex min-h-12 items-center bg-slate-950 px-5 font-black text-white" href={user ? "/dashboard" : "/try"}>{locale === "vi" ? "Đánh giá năng lực" : "Check your level"}<span className="ml-2" aria-hidden="true">→</span></Link></aside></div></header>
    <section className="border-b border-slate-900/10 bg-white/55" aria-label={locale === "vi" ? "Chủ đề" : "Topics"}><div className="mx-auto flex max-w-7xl gap-2 overflow-x-auto px-5 py-4 sm:px-6"><Link className={`shrink-0 rounded-full px-4 py-2 text-sm font-bold ${!activeCategory ? "bg-slate-950 text-white" : "border border-slate-300 bg-white"}`} href="/blog">{locale === "vi" ? "Tất cả" : "All"}</Link>{POST_CATEGORIES.map(item => <Link className={`shrink-0 rounded-full px-4 py-2 text-sm font-bold ${activeCategory === item ? "bg-slate-950 text-white" : "border border-slate-300 bg-white hover:border-teal-600"}`} href={`/blog?category=${item}`} key={item}>{CATEGORY_LABELS[item][locale]}</Link>)}</div></section>
    <section className="mx-auto max-w-7xl px-5 py-10 sm:px-6 sm:py-14"><div className="flex flex-col gap-5 border-b border-slate-900/15 pb-7 md:flex-row md:items-end md:justify-between"><div><p className="text-xs font-black uppercase tracking-[.18em] text-teal-800">{activeCategory ? categoryNotes[activeCategory][locale] : locale === "vi" ? "Mới nhất từ phòng biên tập" : "Latest from the editorial desk"}</p><h2 className="mt-2 text-3xl font-black">{activeCategory ? CATEGORY_LABELS[activeCategory][locale] : locale === "vi" ? "Bài viết nổi bật" : "Featured guides"}</h2></div><form className="flex w-full max-w-md gap-2" method="get">{activeCategory && <input name="category" type="hidden" value={activeCategory}/>}<label className="sr-only" htmlFor="blog-search">{locale === "vi" ? "Tìm bài viết" : "Search articles"}</label><input className="min-h-12 min-w-0 flex-1 border border-slate-300 bg-white px-4 outline-offset-2 focus:outline-2 focus:outline-teal-700" defaultValue={q} id="blog-search" name="q" placeholder={locale === "vi" ? "Tìm: Part 7, từ vựng, 700 điểm…" : "Search: Part 7, vocabulary, 700…"}/><button className="min-h-12 bg-teal-800 px-5 font-black text-white">{locale === "vi" ? "Tìm" : "Search"}</button></form></div>
      {featured ? <div className="mt-8"><ArticleCard featured image={featured.image} locale={locale} post={featured.post}/></div> : <div className="mt-8 border border-dashed border-slate-400 bg-white px-6 py-14 text-center"><h2 className="text-2xl font-black">{locale === "vi" ? "Không tìm thấy bài phù hợp" : "No matching guides"}</h2><p className="mt-3 text-slate-600">{locale === "vi" ? "Thử từ khóa ngắn hơn hoặc xem tất cả chủ đề." : "Try a shorter query or browse every topic."}</p><Link className="mt-5 inline-flex font-black text-teal-800" href="/blog">{locale === "vi" ? "Xem tất cả bài viết" : "View all guides"}</Link></div>}
      {remaining.length > 0 && <div className="mt-7 grid gap-6 md:grid-cols-2 xl:grid-cols-3">{remaining.map(({ post, image }) => <ArticleCard image={image} key={post.id} locale={locale} post={post}/>)}</div>}
    </section>
    {!activeCategory && !query && <section className="bg-slate-950 text-white"><div className="mx-auto max-w-7xl px-5 py-14 sm:px-6"><p className="text-xs font-black uppercase tracking-[.2em] text-teal-300">{locale === "vi" ? "CHỌN THEO MỤC TIÊU" : "CHOOSE BY GOAL"}</p><h2 className="mt-3 text-3xl font-black">{locale === "vi" ? "Bạn muốn cải thiện điều gì trước?" : "What do you want to improve first?"}</h2><div className="mt-8 grid gap-px overflow-hidden border border-white/15 bg-white/15 sm:grid-cols-2 lg:grid-cols-4">{[["LISTENING", locale === "vi" ? "Nghe không kịp" : "Listening feels too fast"], ["READING", locale === "vi" ? "Luôn thiếu giờ Reading" : "Running out of Reading time"], ["GRAMMAR", locale === "vi" ? "Part 5 sai nhiều" : "Too many Part 5 errors"], ["STUDY_PLAN", locale === "vi" ? "Không duy trì được lịch học" : "Can't keep a study routine"]].map(([key, label]) => <Link className="group bg-slate-950 p-6 hover:bg-teal-950" href={`/blog?category=${key}`} key={key}><span className="text-lg font-black">{label}</span><span className="mt-6 block text-teal-300 transition-transform group-hover:translate-x-1">{locale === "vi" ? "Xem hướng dẫn" : "See guides"} →</span></Link>)}</div></div></section>}
    <PublicFooter locale={locale}/>
  </main>;
}
